(4669173, 674180, 41675, '<td valign="top">Hmmm, not quite sure what this is, but it looks interesting. I like the shapes. The color comes across very orange/yellowish.</td>', 'Hmmm, not quite sure what this is, but it looks interesting. I like the shapes. The color comes across very orange/yellowish.', '2008-04-30 22:19:52.000000', NULL, 1),
(4669175, 674391, 41675, '<td valign="top">Very nice. I like so many different things about your photo. The water droplets, the sun shining on the vine hairs and the way you composed the sun bursting through the one bunch. This would have been great for that new sun challenge. Lol. Best of luck in the challenge. One of my favorites so far.</td>', 'Very nice. I like so many different things about your photo. The water droplets, the sun shining on the vine hairs and the way you composed the sun bursting through the one bunch. This would have been great for that new sun challenge. Lol. Best of luck in the challenge. One of my favorites so far.', '2008-04-30 22:21:18.000000', NULL, 1),
(4669176, 674525, 41675, '<td valign="top">Wow! Now that''s some green lettuce! Perhaps a bit too green? I like the tight close up and water droplets.</td>', 'Wow! Now that''s some green lettuce! Perhaps a bit too green? I like the tight close up and water droplets.', '2008-04-30 22:22:17.000000', NULL, 1),
(4669180, 673932, 41675, '<td valign="top">Good lighting and composition. The veggies seems maybe a bit...."squished" in the frame to me and the plate is nearly invisible unless you really look, but otherwise very nicely done. 8</td>', 'Good lighting and composition. The veggies seems maybe a bit...."squished" in the frame to me and the plate is nearly invisible unless you really look, but otherwise very nicely done. 8', '2008-04-30 22:23:21.000000', NULL, 1),
(4669182, 673997, 41675, '<td valign="top">I like your concept and composition. For me, the background detracts from your set up. Perhaps a different angle or a darker background would enhance the overall look of your image.</td>', 'I like your concept and composition. For me, the background detracts from your set up. Perhaps a different angle or a darker background would enhance the overall look of your image.', '2008-04-30 22:24:04.000000', NULL, 1),
