(4669185, 673230, 41675, '<td valign="top">Very creative idea and nicely executed. The image seems maybe a bit too light, but again, a great photo. Should be in the top five.</td>', 'Very creative idea and nicely executed. The image seems maybe a bit too light, but again, a great photo. Should be in the top five.', '2008-04-30 22:25:16.000000', NULL, 1),
(4669187, 674590, 41675, '<td valign="top">Personally, I am not a big veggie fan, but your image looks really good. I like the composition, lighting and colors.</td>', 'Personally, I am not a big veggie fan, but your image looks really good. I like the composition, lighting and colors.', '2008-04-30 22:25:48.000000', NULL, 1),
