(4671024, 673298, 30049, '<td valign="top">Nice color tones.  Image is a bit static and centered IMO.  Maybe a second tomato, move the whole one left, and have a couple of slices made on the second?  Just a thought.  :-)  Good luck!</td>', 'Nice color tones.  Image is a bit static and centered IMO.  Maybe a second tomato, move the whole one left, and have a couple of slices made on the second?  Just a thought.  :-)  Good luck!', '2008-05-01 12:04:16.000000', NULL, 1),
(4671031, 673932, 30049, '<td valign="top">Certainly fresh, colorful, and appealing.  Perhaps a touch of fill/bounce light to lighten the shadows a touch?</td>', 'Certainly fresh, colorful, and appealing.  Perhaps a touch of fill/bounce light to lighten the shadows a touch?', '2008-05-01 12:05:18.000000', NULL, 1),
(4671033, 673950, 674, '<td valign="top">lovely composition, a bit less flash and more detail in the rice would have made this a 10 for me 8</td>', 'lovely composition, a bit less flash and more detail in the rice would have made this a 10 for me 8', '2008-05-01 12:05:18.000000', NULL, 1),
(4671036, 674404, 674, '<td valign="top">the focus doesnt appear quite right somehow!</td>', 'the focus doesnt appear quite right somehow!', '2008-05-01 12:06:06.000000', NULL, 1),
(4671039, 674112, 674, '<td valign="top">nice texture shot a little blown out in spots!</td>', 'nice texture shot a little blown out in spots!', '2008-05-01 12:06:50.000000', NULL, 1),
