(4671047, 674110, 674, '<td valign="top">Nice idea but perhaps the it would work better if the letters were all the same colour.</td>', 'Nice idea but perhaps the it would work better if the letters were all the same colour.', '2008-05-01 12:08:04.000000', NULL, 1),
