(4673129, 674556, 81691, '<td valign="top">Definitely not something I would want to come across in a health food magazine - this does not look delicious.</td>', 'Definitely not something I would want to come across in a health food magazine - this does not look delicious.', '2008-05-01 22:23:22.000000', NULL, 1),
(4673136, 673952, 81691, '<td valign="top">Top marks for creativity and presentation.  A picture like this belongs in a health food magazine.  Well done!</td>', 'Top marks for creativity and presentation.  A picture like this belongs in a health food magazine.  Well done!', '2008-05-01 22:25:12.000000', NULL, 1),
(4673141, 674226, 81691, '<td valign="top">Excellent shot, very well done!  I love the humor here.</td>', 'Excellent shot, very well done!  I love the humor here.', '2008-05-01 22:26:09.000000', NULL, 1),
(4673228, 672389, 34938, '<td valign="top">I think the focus point is right at the edge of the chopsticks and the soy sauce, and also the matting looks sharp which probably means your focus point is below the plate itself. It is really unusual as the food looks really soft. I like the colours and composition but it''s hard to get around the softness of the food. I think the focus should have been around the centre of the food on the mango perhaps. I do like lots of depth of field in food photos, but this has a strange focus thing happening...is your lens out of whack?</td>', 'I think the focus point is right at the edge of the chopsticks and the soy sauce, and also the matting looks sharp which probably means your focus point is below the plate itself. It is really unusual as the food looks really soft. I like the colours and composition but it''s hard to get around the softness of the food. I think the focus should have been around the centre of the food on the mango perhaps. I do like lots of depth of field in food photos, but this has a strange focus thing happening...is your lens out of whack?', '2008-05-01 23:14:45.000000', NULL, 1),
(4673285, 674586, 72068, '<td valign="top">Fat free cheese? Eww.</td>', 'Fat free cheese? Eww.', '2008-05-01 23:46:52.000000', NULL, 1),
