(4677747, 674393, 61818, '<td valign="top">Very appealing, though pasta as a health food is an argument I would like to win with my doctor.  Composition is nice.  Not voting.</td>', 'Very appealing, though pasta as a health food is an argument I would like to win with my doctor.  Composition is nice.  Not voting.', '2008-05-03 17:46:52.000000', NULL, 1),
(4677751, 673753, 61818, '<td valign="top">Not voting, just commenting.  Composition is pretty rough, lighting is not appealing.  The photo takes some very tasty components and actually makes them look rather unappealing.</td>', 'Not voting, just commenting.  Composition is pretty rough, lighting is not appealing.  The photo takes some very tasty components and actually makes them look rather unappealing.', '2008-05-03 17:48:10.000000', NULL, 1),
(4677753, 674587, 61818, '<td valign="top">Nice composition.  A tad underexposed to my eyes, and the focus could be a bit better on the fruit in the spoon.  Not voting just commenting.</td>', 'Nice composition.  A tad underexposed to my eyes, and the focus could be a bit better on the fruit in the spoon.  Not voting just commenting.', '2008-05-03 17:48:56.000000', NULL, 1),
(4677755, 674550, 61818, '<td valign="top">Not voting just commenting.  Good focus and nice details on the water drops.  Composition is poor and its nearly impossible to tell what exactly the chips are.  The photo presents the wrong object as the subject - it makes the water drops and plastic bag look very appealing.</td>', 'Not voting just commenting.  Good focus and nice details on the water drops.  Composition is poor and its nearly impossible to tell what exactly the chips are.  The photo presents the wrong object as the subject - it makes the water drops and plastic bag look very appealing.', '2008-05-03 17:50:34.000000', NULL, 1),
(4677759, 674518, 61818, '<td valign="top">Not voting just commenting.  Lighting is nice/soothing, focus is good.  Would prefer if the entire bowl were in frame and the composition slightly less tight.  Little bit of (red? yellow?) color would also add a bit of interest to all the greens.</td>', 'Not voting just commenting.  Lighting is nice/soothing, focus is good.  Would prefer if the entire bowl were in frame and the composition slightly less tight.  Little bit of (red? yellow?) color would also add a bit of interest to all the greens.', '2008-05-03 17:52:15.000000', NULL, 1),
(4677760, 672828, 61818, '<td valign="top">Not voting just commenting.  Odd choice to shoot the subject through the bowl, but you managed to do so without a lot of light reflections and the focus is good.  Composition could be better.</td>', 'Not voting just commenting.  Odd choice to shoot the subject through the bowl, but you managed to do so without a lot of light reflections and the focus is good.  Composition could be better.', '2008-05-03 17:53:10.000000', NULL, 1),
(4677764, 674181, 61818, '<td valign="top">Not voting just commenting.  Lot of colors there that look a bit dull.  Either underexposed or just not blasted with enough light when shot.  Composition is nice and you arranged all the bits and pieces in a pleasing manner.</td>', 'Not voting just commenting.  Lot of colors there that look a bit dull.  Either underexposed or just not blasted with enough light when shot.  Composition is nice and you arranged all the bits and pieces in a pleasing manner.', '2008-05-03 17:54:11.000000', NULL, 1),
(4677768, 673191, 61818, '<td valign="top">Not voting just commenting.  Lighting is ok, dof is a little too shallow in my opinion (is the stem really the important part of the subject?).  Not a lot to get engaged in here.</td>', 'Not voting just commenting.  Lighting is ok, dof is a little too shallow in my opinion (is the stem really the important part of the subject?).  Not a lot to get engaged in here.', '2008-05-03 17:54:55.000000', NULL, 1),
